/* UI regression audit of frozen predictions, not additional simulator episodes. */
const fs=require('node:fs'),path=require('node:path'),S=require('./sampling.js');
const out=process.argv[2];if(!out)throw Error('Output directory required');const reportPath=path.join(out,'set-audit.json');if(fs.existsSync(reportPath))throw Error('Refusing to overwrite audit');const start=performance.now();
const D=JSON.parse(fs.readFileSync(path.join(out,'viewer/data.js'),'utf8').slice(11,-1));const sets=[];const seed=20260911;
for(const [model,qs] of Object.entries(D.prob))for(let m=0;m<qs.length;m++)for(const mode of ['raw','projected'])for(const count of [3,5]){const clear=D.lower[m].map(v=>v>=.02),weights=mode==='raw'?qs[m]:S.condition(qs[m],clear).q,s=S.sampleSet({weights,count,seed});let overlaps=0;for(let i=0;i<s.uniqueCells.length;i++)for(let j=i+1;j<s.uniqueCells.length;j++)if(S.overlaps(D.routeSpec[m][s.uniqueCells[i]],D.routeSpec[m][s.uniqueCells[j]]))overlaps++;const anyHit=s.uniqueCells.some(c=>D.upper[m][c]<0),anyUnknown=s.uniqueCells.some(c=>D.lower[m][c]<.02&&D.upper[m][c]>=0),allClear=s.abstentions===0&&s.uniqueCells.every(c=>clear[c]),mass=S.normalize(weights).q.reduce((a,p,i)=>a+p*clear[i],0);sets.push({model,motion:D.motions[m].id,mode,count,seed,cells:s.draws.map(d=>d.cell),uniqueCells:s.uniqueCells.length,eventsCovered:new Set(s.uniqueCells.map(c=>Math.floor(c/45))).size,abstentions:s.abstentions,referenceClearSet:allClear,anyPenetrationWitness:anyHit,anyUnknown,primitiveOverlapPairs:overlaps,analyticIndependentClearSetProbability:mass**count,physicalPass:null});}
const aggregates=[];for(const model of Object.keys(D.prob))for(const mode of ['raw','projected'])for(const count of [3,5]){const rows=sets.filter(r=>r.model===model&&r.mode===mode&&r.count===count);aggregates.push({model,mode,count,sets:rows.length,referenceClearSets:rows.filter(r=>r.referenceClearSet).length,setsWithPenetrationWitness:rows.filter(r=>r.anyPenetrationWitness).length,setsWithUnknown:rows.filter(r=>r.anyUnknown).length,setsWithPrimitiveOverlap:rows.filter(r=>r.primitiveOverlapPairs>0).length,abstainedSets:rows.filter(r=>r.abstentions>0).length,meanEventsCovered:rows.reduce((a,r)=>a+r.eventsCovered,0)/rows.length,physicalPasses:null});}
// Distribution integrity on the actual default learned q, with a fixed test seed.
const q=S.normalize(D.prob['hindsight-801'][0]).q,N=100000,counts=q.map(()=>0),r=S.rng(93218);for(let i=0;i<N;i++)counts[S.categorical(q,r())]++;const maxAbsoluteFrequencyError=Math.max(...q.map((v,i)=>Math.abs(counts[i]/N-v)));if(maxAbsoluteFrequencyError>.005)throw Error('Categorical frequency regression');
fs.writeFileSync(reportPath,JSON.stringify(sets,null,2));fs.writeFileSync(path.join(out,'set-aggregate.json'),JSON.stringify(aggregates,null,2));const keys=Object.keys(sets[0]);fs.writeFileSync(path.join(out,'set-audit.csv'),keys.join(',')+'\n'+sets.map(row=>keys.map(k=>{const v=typeof row[k]==='object'?JSON.stringify(row[k]):String(row[k]);return '"'+v.replaceAll('"','""')+'"';}).join(',')).join('\n')+'\n');const receipt={scope:'UI regression audit using frozen labels; zero new training or physics',seed,sets:sets.length,categoricalRegressionDraws:N,maxAbsoluteFrequencyError,frequencyTestTolerance:.005,wallSeconds:(performance.now()-start)/1000,physicsSteps:0,optimizerUpdates:0,sourceDefaultCells:S.sampleSet({weights:q,count:3,seed}).draws.map(d=>d.cell)};fs.writeFileSync(path.join(out,'sampling-validation.json'),JSON.stringify(receipt,null,2));console.log(receipt);
